def pre_suggestion_description(source):
    from text_edit_mode_scope_contract import pre_text_edit_mode
    source = pre_text_edit_mode(source)
    for _, old, new, count in reversed(CHANGES):
        if new in source:
            assert source.count(new) == count
            source = source.replace(new, old)
    return source

def pre_suggestion_description_bytes(path):
    data = path.read_bytes()
    return pre_suggestion_description(data.decode()).encode() if path.suffix == '.swift' else data

